```python
# Initialize an empty dictionary to store names and phone numbers
name_phone_dict = {}

def add_name(name, phone_number):
    """Add a name and phone number to the dictionary."""
    if name not in name_phone_dict:
        name_phone_dict[name] = phone_number
        print(f"{name}: {phone_number}")
    else:
        print(f"Name '{name}' already exists. Phone number for this name will be updated.")
        del name_phone_dict[name]
        name_phone_dict[name] = phone_number
        print(f"{name}: {phone_number}")

def remove_name(name):
    """Remove a name and its corresponding phone number from the dictionary."""
    if name in name_phone_dict:
        del name_phone_dict[name]
        print(f"Name '{name}' removed.")
    else:
        print(f"Name '{name}' not found.")

def search_name(name):
    """Search for a name and its corresponding phone number in the dictionary."""
    if name in name_phone_dict:
        print(f"{name}: {name_phone_dict[name]}")
    else:
        print(f"Name '{name}' not found.")

# Sample input and output
sample_input = "add John 123456, remove Jane, search John"
sample_input_list = sample_input.split(",")

for input_item in sample_input_list:
    command, name, phone_number = input_item.strip().split()

    if command == "add":
        add_name(name, phone_number)
    elif command == "remove":
        remove_name(name)
    elif command == "search":
        search_name(name)
